  "contradictory_card_ids": [
    "C03"
  ],
  "decision_summary": "Direct absolute oral bioavailability values in healthy subjects for multiple transferred molecules are ≥41%, strongly supporting high bioavailability; one ordinary-condition absolute value is 11%, but the preponderance of direct threshold-relevant evidence supports F ≥ 20%.",
